        a[0] = 2;
        a = new int[] {3};
    }
    public static void main(String[] args) {
        int[] a = {1};
        change(a);
        System.out.println(a[0]);
    }
}

class Main {
    static int sum(int n) {
        if (n == 0) {
            return 0;
        }
        return n + sum(n - 1);
    }
    public static void main(String[] args) {
        System.out.println(sum(3));
    }
}
